function FoodPage(){const {data,date,open}=useApp();const navigate=useNavigate();return <><PageHeading title="Food log" subtitle="Log each meal. Keep your daily nutrition in view." action={<button className="button" onClick={()=>open('food')}>Log Food</button>}/><QuickEntry/><div className="day-row"><DateControl/><button className="text-button" onClick={()=>navigate('/supplements')}>Supplements →</button></div><div className="command-columns"><div><Card><MealRows/></Card><p className="help">Catalog values are estimates. Add label values when available.</p></div><NutrientOverview key={date} data={data} date={date}/></div></>}
function FoodModal({ onClose, initialMeal = 'Breakfast' }: any) { const { data, update, date, notify } = useApp(); const [query, setQuery] = useState(''), [category, setCategory] = useState('All foods'), [selected, setSelected] = useState<Food | null>(null), [quantity, setQuantity] = useState(1), [unit, setUnit] = useState(''), [meal, setMeal] = useState(initialMeal), [error, setError] = useState(''); const debouncedQuery = useDebouncedValue(query); const [limit, setLimit] = useState(50); useEffect(() => setLimit(50), [debouncedQuery, category]); const catalog = [...new Map([...foods, ...data.entries.map(e => e.food), ...data.recipes.map(recipeFood)].map(f => [f.id, f])).values()]; const filtered = searchFoods(catalog.filter(f => category === 'All foods' || (category === 'Recent' ? data.entries.some(e => e.food.id === f.id) : f.category === category)), debouncedQuery); let scaled: any = null; try { if (selected) scaled = portion(selected, quantity, unit) } catch { } return <Modal title="Add to your food journal" description={`${dateLabel(date)} · choose a food and confirm your portion.`} onClose={onClose}><div className="search-input"><Search size={18} /><input autoFocus aria-label="Search foods" placeholder="Search biryani, eggs, roti…" value={query} onChange={e => setQuery(e.target.value)} /></div><Field label="Food category"><select value={category} onChange={e => setCategory(e.target.value)}>{['All foods', 'Pakistani Cuisine', 'Recent', ...new Set(catalog.map(f => f.category).filter(c => c !== 'Pakistani Cuisine'))].map(c => <option key={c}>{c}</option>)}</select></Field>{!selected ? <><button className="text-button" onClick={() => { setSelected({ id: crypto.randomUUID(), name: '', category: 'Custom food', grams: 100, unit: 'serving', ...zero, source: 'User-entered nutrition' }); setUnit('serving'); setQuantity(1) }}>+ Add a custom food</button><div className="food-results">{filtered.length ? filtered.slice(0, limit).map(f => <button key={f.id} className="food-result" onClick={() => { setSelected(f); setUnit(f.unit); setQuantity(1) }}><span className="food-letter">{f.name.slice(0, 1)}</span><span><strong>{f.name}</strong><small>1 {f.unit} · {f.grams} g · {f.category}</small></span><b>{f.calories}<small>kcal</small></b><Plus size={17} /></button>) : <Empty title="No matching foods" text="Try a different food name or clear your filters." />}</div>{filtered.length > limit && <button className="button secondary" onClick={() => setLimit(value => value + 50)}>Show more foods ({filtered.length - limit} remaining)</button>}</> : <><button className="text-button back" onClick={() => setSelected(null)}><ChevronLeft size={15} />Back to foods</button>{selected.category === 'Custom food' && <><Field label="Food name"><input value={selected.name} onChange={e => setSelected({ ...selected, name: e.target.value })} /></Field><Field label="Grams in one serving"><input type="number" min="1" value={selected.grams} onChange={e => setSelected({ ...selected, grams: +e.target.value })} /></Field><div className="form-grid two">{(['calories', 'protein', 'carbs', 'fat', 'fiber'] as const).map(k => <Field key={k} label={k + ' per serving'}><input type="number" min="0" step="0.1" value={selected[k]} onChange={e => setSelected({ ...selected, [k]: +e.target.value })} /></Field>)}</div><NutrientFields value={selected.details} onChange={details=>setSelected({...selected,details})}/></>}<div className="selected-food"><h3>{selected.name}</h3><p>{selected.source}</p><small>{selected.note}</small></div><div className="form-grid"><Field label="Quantity"><input type="number" min="0.1" step="0.1" value={quantity} onChange={e => setQuantity(+e.target.value)} /></Field><Field label="Unit"><select value={unit} onChange={e => setUnit(e.target.value)}>{[...new Set([selected.unit, 'g', ...Object.keys(selected.units || {})])].map(u => <option key={u}>{u}</option>)}</select></Field><Field label="Meal"><select value={meal} onChange={e => setMeal(e.target.value)}>{['Breakfast', 'Lunch', 'Dinner', 'Snacks'].map(m => <option key={m}>{m}</option>)}</select></Field></div>{scaled && <div className="nutrition-preview">{[['Calories', scaled.nutrition.calories, 'kcal'], ['Protein', scaled.nutrition.protein, 'g'], ['Carbs', scaled.nutrition.carbs, 'g'], ['Fat', scaled.nutrition.fat, 'g']].map(([label, v, u]) => <div key={label as string}><strong>{fmt(v as number)} <small>{u}</small></strong><span>{label}</span></div>)}<NutritionDetails details={scaled.nutrition.details}/><p>Converted portion: approximately {fmt(scaled.grams)} g</p></div>}{error && <p className="error" role="alert">{error}</p>}<button className="button full" onClick={async () => { try { if (!selected.name.trim() || !Number.isFinite(selected.grams) || selected.grams <= 0 || [selected.calories, selected.protein, selected.carbs, selected.fat, selected.fiber].some(v => !Number.isFinite(v) || v < 0)) throw Error('Enter a food name, valid serving weight and nonnegative nutrition.'); const p = portion(selected, quantity, unit); if (await update(s => ({ ...s, entries: [...s.entries, { id: crypto.randomUUID(), date, meal, food: { ...selected }, quantity, unit, ...p }] }))) onClose() } catch (e) { setError((e as Error).message) } }}><Plus size={17} />Add to {meal.toLowerCase()}</button></>}</Modal> }
function ProfileModal({ onClose }: any) { const { data, update } = useApp(); const [p, setP] = useState<Partial<Profile>>(data.profile || { name: '', sex: 'female', activity: 1.2, goal: 'maintenance', special: false }), [error, setError] = useState(''); const field = (k: keyof Profile, v: any) => setP({ ...p, [k]: v }); const t = targets(p as Profile); return <Modal title="Make it personal" description="Adult fitness estimates, shaped around your starting point." onClose={onClose}><form onSubmit={async e => { e.preventDefault(); const parsed = profileSchema.safeParse(p); if (!parsed.success) { setError(parsed.error.issues[0].message); return } if (await update(s => ({ ...s, profile: parsed.data }))) onClose() }}><Field label="Your name"><input required value={p.name || ''} onChange={e => field('name', e.target.value)} /></Field><div className="form-grid"><Field label="Age (18–100)"><input required type="number" min="18" max="100" value={p.age || ''} onChange={e => field('age', +e.target.value)} /></Field><Field label="Weight (kg)"><input required type="number" min="30" max="300" step="0.1" value={p.weight || ''} onChange={e => field('weight', +e.target.value)} /></Field><Field label="Height (cm)"><input required type="number" min="120" max="230" value={p.height || ''} onChange={e => field('height', +e.target.value)} /></Field></div><div className="form-grid two"><Field label="BMR equation"><select value={p.sex} onChange={e => field('sex', e.target.value)}><option value="female">Female equation</option><option value="male">Male equation</option></select></Field><Field label="Activity level"><select value={p.activity} onChange={e => field('activity', +e.target.value)}>{[[1.2, 'Sedentary'], [1.375, 'Light'], [1.55, 'Moderate'], [1.725, 'Active'], [1.9, 'Very active']].map(([v, l]) => <option key={v} value={v}>{l}</option>)}</select></Field></div><p className="help">The published Mifflin–St Jeor formula uses a sex-specific constant. Select the equation appropriate for your needs with a qualified professional if unsure.</p><Field label="Your goal"><select value={p.goal} onChange={e => field('goal', e.target.value)}><option value="maintenance">Maintain weight</option><option value="loss">Fat loss</option><option value="gain">Muscle gain</option></select></Field><label className="checkbox-label"><input type="checkbox" checked={p.special || false} onChange={e => field('special', e.target.checked)} />Pregnancy, breastfeeding, eating-disorder history, or another situation needing individual guidance — skip automatic targets.</label><div className="notice">{t ? `Estimated daily target: ${fmt(t.calories)} kcal · ${t.protein} g protein. This is a starting estimate, not a medical prescription.` : 'Enter your measurements to calculate targets, or keep logging without a target.'}</div>{error && <p className="error">{error}</p>}<button className="button full" type="submit">Save profile</button></form></Modal> }
function WeightModal({ onClose }: any) { const { data, update, date } = useApp(); return <Modal title="Weight check-in" description="Your original measurement is stored in kilograms; display units never change your history." onClose={onClose}><Suspense fallback={<p>Loading…</p>}><WeightEntry data={data} save={update} date={date} done={onClose}/></Suspense></Modal> }
function WorkoutModal({ onClose }: any) { const { data, update, date } = useApp(); const [index, setIndex] = useState(0), [minutes, setMinutes] = useState(30), [weight, setWeight] = useState(data.profile?.weight || 0); const a = activities[index]; let kcal = 0; try { kcal = workoutCalories(a.met, weight, minutes) } catch { } return <Modal title="Log your movement" description="Count active movement time, excluding rests." onClose={onClose}><form onSubmit={async e => { e.preventDefault(); const calories = workoutCalories(a.met, weight, minutes); if (await update(s => ({ ...s, workouts: [...s.workouts, { id: crypto.randomUUID(), date, name: a.name, minutes, calories }] }))) onClose() }}><Field label="Activity"><select value={index} onChange={e => setIndex(+e.target.value)}>{activities.map((a, i) => <option value={i} key={a.name}>{a.name}</option>)}</select></Field><div className="form-grid two"><Field label="Active minutes"><input type="number" min="1" max="600" required value={minutes} onChange={e => setMinutes(+e.target.value)} /></Field><Field label="Your weight (kg)"><input type="number" min="30" max="300" required value={weight || ''} onChange={e => setWeight(+e.target.value)} /></Field></div><div className="estimate"><Flame size={24} /><strong>{kcal} kcal</strong><span>estimated exercise energy</span></div><p className="help">MET × 3.5 × weight ÷ 200 × active minutes. Activity categories are approximations, not personal measurements. Rest is excluded.</p><button className="button full">Save workout</button></form></Modal> }
function EditWorkout({ workout, onClose }: { workout: Store['workouts'][number]; onClose: () => void }) { const { update } = useApp(); const [w, setW] = useState(workout), [error, setError] = useState(''), [busy, setBusy] = useState(false); return <Modal title="Edit activity" description="Changing active minutes scales the original calorie estimate." onClose={onClose}><form onSubmit={async e => { e.preventDefault(); if (!w.name.trim() || !Number.isFinite(w.minutes) || w.minutes <= 0 || w.minutes > 1440) { setError('Enter a name and valid active duration.'); return } setBusy(true); const next = { ...w, calories: Math.round(workout.calories * w.minutes / workout.minutes) }; if (await update(s => ({ ...s, workouts: s.workouts.map(x => x.id === w.id ? next : x) }))) onClose(); setBusy(false) }}><Field label="Activity name"><input required value={w.name} onChange={e => setW({ ...w, name: e.target.value })} /></Field><Field label="Active minutes"><input required type="number" min="0.1" max="1440" step="0.1" value={w.minutes} onChange={e => setW({ ...w, minutes: +e.target.value })} /></Field><div className="form-grid">{(['sets', 'reps', 'weightKg'] as const).map(k => <Field key={k} label={k === 'weightKg' ? 'Weight (kg)' : k}><input type="number" min="0" max="500" value={w[k] ?? 0} onChange={e => setW({ ...w, [k]: +e.target.value })} /></Field>)}</div>{error && <p className="error">{error}</p>}<button className="button full" disabled={busy}>{busy ? 'Saving…' : 'Save changes'}</button></form></Modal> }
function Workouts() { const { data, update, date, open } = useApp(); const navigate = useNavigate(); const [editing, setEditing] = useState<Store['workouts'][number] | null>(null); const list = data.workouts.filter(w => w.date === date); return <>{editing && <EditWorkout workout={editing} onClose={() => setEditing(null)} />}<PageHeading title="Your movement, logged" subtitle="Choose an exercise, follow the guide and record what you completed." action={<button className="button" onClick={() => open('workout')}><Plus size={17} />Log workout</button>} /><div className="hero-actions"><button className="button secondary" onClick={()=>open('custom-workout')}>Add custom workout</button><button className="button secondary" onClick={() => navigate('/exercise-library')}>Browse exercise library <ArrowRight size={16} /></button></div><div className="day-row"><h3>Your activity</h3><DateControl /></div><div className="stat-grid"><Stat label="Logged activities" value={list.length} /><Stat label="Active time" value={list.reduce((a, w) => a + w.minutes, 0)} unit="min" /><Stat label="Exercise estimate" value={list.reduce((a, w) => a + w.calories, 0)} unit="kcal" /></div><Card>{list.length ? list.map(w => <div className="record" key={w.id}><span className="soft-icon"><Dumbbell size={22} /></span><div><strong>{w.name}</strong><p>{fmt(w.minutes)} active minutes · {w.calories} estimated kcal {w.sets ? `· ${w.sets} sets × ${w.reps ?? 0} reps · ${w.weightKg ?? 0} kg` : ""}</p></div><button className="text-button" onClick={() => setEditing(w)}>Edit</button><IconButton label={'Delete ' + w.name} onClick={() => update(s => removeWorkout(s, w.id))}><Trash2 size={17} /></IconButton></div>) : <Empty icon={Dumbbell} title="Room for a little movement" text="Your recorded activities will appear here." action="Log a workout" onClick={() => open('workout')} />}</Card></> }
function Stat({ label, value, unit }: any) { return <Card className="stat"><span>{label}</span><strong>{typeof value === 'number' ? fmt(value) : value}<small>{unit}</small></strong></Card> }
function Plans() { const { data, update, date, open } = useApp(); const [day, setDay] = useState(0), [durations, setDurations] = useState<Record<string, number>>({}); const p = programs[day], level = data.level, id = sessionKey(date, day, level), done = data.completed[id] || []; return <><PageHeading eyebrow="A LITTLE STRUCTURE, A LOT OF POSSIBILITY" title="Your weekly movement plan" subtitle="Five days of home-friendly strength, movement, and recovery." /><div className="plan-controls"><div className="segmented">{['Beginner', 'Intermediate', 'Advanced'].map(l => <button className={level === l ? 'active' : ''} key={l} onClick={() => update(s => ({ ...s, level: l }))}>{l}</button>)}</div><DateControl /></div><div className="day-tabs">{['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday'].map((d, i) => <button className={day === i ? 'active' : ''} onClick={() => setDay(i)} key={d}><small>{d}</small><strong>{programs[i].name}</strong></button>)}</div><Card className="plan-banner"><div><span className="eyebrow">{level.toUpperCase()} · DAY {day + 1}</span><h2>{p.name}</h2><p>{p.focus}</p><div className="inline-meta"><span><Dumbbell size={15} />{p.equipment}</span><span><Clock size={15} />{day === 3 ? '20' : '30–45'} min including rest</span><span>{p.exercises.length} movements</span></div></div><span className="plan-big-icon"><Activity size={58} strokeWidth={1.2} /></span></Card><div className="notice"><Info size={18} />Illustrated movement guides show the basic motion, not a full form tutorial. Use a comfortable range and stop if a movement hurts.</div><p className="help">Tick each movement to save its estimated calories to your daily exercise total. Untick to remove it. A new day starts fresh. Estimates use your profile weight and active minutes.</p><Card title={date === dayKey() ? "Today’s session" : `Session · ${dateLabel(date)}`} subtitle={day === 3 ? 'Gentle movement at every level. Keep the effort easy.' : 'Start with 5 minutes of gentle marching, arm circles, and comfortable mobility.'} action={<span className="badge">{done.length} / {p.exercises.length} complete</span>}><Progress value={done.length} max={p.exercises.length} />{p.exercises.map((name, i) => <div className="exercise" key={name}><ExerciseDemo name={name} /><div className="exercise-detail"><span className="eyebrow">MOVEMENT {String(i + 1).padStart(2, '0')}</span><strong>{name}</strong><p className="exercise-calories">{data.profile ? `≈ ${fmt(data.workouts.find(w => w.identity === id + '::' + name)?.calories ?? exerciseEstimate(name, day, level, data.profile.weight, durations[id + name]).calories)} kcal` : 'Add your weight to estimate calories'}</p><label className="exercise-duration">Active minutes <input aria-label={`Active minutes for ${name}`} type="number" min="0.5" max="180" step="0.5" disabled={done.includes(name)} value={data.workouts.find(w => w.identity === id + '::' + name)?.minutes ?? durations[id + name] ?? exerciseEstimate(name, day, level, 70).minutes} onChange={e => { const minutes = +e.target.value; if (Number.isFinite(minutes) && minutes >= 0.5 && minutes <= 180) setDurations(v => ({ ...v, [id + name]: minutes })) }} /></label><p>{day === 3 ? 'Gentle, comfortable range · 1–2 minutes' : `${level === 'Beginner' ? '3' : level === 'Intermediate' ? '4' : '4'} sets · ${day === 2 ? '40 sec work / 20 sec rest' : '10–15 controlled reps · 45–60 sec rest'}`}</p><small>{level === 'Advanced' && day !== 3 ? 'Use a slower lowering phase and a controlled pause. ' : ''}Keep breathing and use a comfortable range of motion.</small></div><label className="exercise-done"><input type="checkbox" checked={done.includes(name)} onChange={() => { if (!data.profile) { open('profile'); return } const minutes = durations[id + name]; if (minutes !== undefined && (!Number.isFinite(minutes) || minutes < 0.5 || minutes > 180)) return; update(s => togglePlannedExercise(s, date, day, level, name, minutes)) }} aria-label={`${name}: completed on ${date}`} /><span>{date === dayKey() ? 'Done today' : 'Done this day'}</span></label></div>)}<div className="plan-end"><p>Completed exercises sync automatically to Workouts, Dashboard and Analytics. Calories are approximate activity-category estimates, not measured burn.</p><a className="text-button" href="https://pacompendium.com/conditioning-exercise/" target="_blank" rel="noreferrer">Estimate source</a></div></Card></> }
function Calendar() { const { data, date, setDate } = useApp(), [month, setMonth] = useState(date.slice(0, 7)); const start = month + '-01', offset = (new Date(start + 'T12:00:00').getDay() + 6) % 7, days = new Date(+month.slice(0, 4), +month.slice(5, 7), 0).getDate(); return <><PageHeading title="Your journal calendar" subtitle="Choose a date to revisit your meals and movement." /><Card title={new Date(start + 'T12:00:00').toLocaleDateString(undefined, { month: 'long', year: 'numeric' })} action={<div className="inline-meta"><IconButton label="Previous month" onClick={() => setMonth(shiftDay(start, -1).slice(0, 7))}><ChevronLeft size={19} /></IconButton><IconButton label="Next month" onClick={() => setMonth(shiftDay(start, 32).slice(0, 7))}><ChevronRight size={19} /></IconButton></div>}><div className="calendar-grid">{['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(d => <div className="calendar-weekday" key={d}>{d}</div>)}{Array.from({ length: offset }, (_, i) => <span key={'blank' + i} />)}{Array.from({ length: days }, (_, i) => { const d = `${month}-${String(i + 1).padStart(2, '0')}`, entries = data.entries.filter(e => e.date === d), w = data.workouts.filter(e => e.date === d); return <button className={d === date ? 'selected' : ''} key={d} onClick={() => setDate(d)}><strong>{i + 1}</strong>{entries.length > 0 && <span>{fmt(total(entries.map(e => e.nutrition)).calories)} kcal</span>}{w.length > 0 && <small><Dumbbell size={12} />{w.length} workout</small>}{!entries.length && !w.length && <small className="calendar-empty">—</small>}</button> })}</div></Card><div className="section-title"><h2>{dateLabel(date)}</h2></div><Card><MealRows /></Card></> }
function history(data: Store, date: string) { return Array.from({ length: 7 }, (_, i) => { const d = shiftDay(date, i - 6), balance = dailyBalance(data, d); return { date: d, day: new Date(d + 'T12:00:00').toLocaleDateString('en', { weekday: 'short' }), intake: data.entries.some(e => e.date === d) || data.supplements.some(s => s.taken.includes(d)) || data.supplementHistory.some(r => r.date === d) ? Math.round(balance.nutrients.calories) : null, exercise: balance.burned } }) }
function Analytics() { const { data, date } = useApp(); return <Suspense fallback={<p role="status">Loading analytics…</p>}><AnalyticsView data={data} date={date} /></Suspense> }
function Insights() { const { data, date, open } = useApp(); return <Suspense fallback={<p role="status">Loading insights…</p>}><InsightsView data={data} date={date} open={open} /></Suspense> }
function Recipes() { const { data, date, update, notify, open, guest } = useApp(); return <Suspense fallback={<p role="status">Loading recipes…</p>}><RecipeStudio data={data} date={date} save={update} notify={notify} open={open} guest={guest} /></Suspense> }
function RecipeModal({ onClose }: any) { const { update } = useApp(); const [name, setName] = useState(''), [yieldN, setYield] = useState(2), [ingredients, setIngredients] = useState<Recipe['ingredients']>([]), [foodId, setFoodId] = useState(foods[0].id), [q, setQ] = useState(1); const f = foods.find(f => f.id === foodId)!; return <Modal title="Create a recipe" description="Ingredient estimates are preserved with your recipe." onClose={onClose}><form onSubmit={async e => { e.preventDefault(); if (!ingredients.length) return; if (await update(s => ({ ...s, recipes: [...s.recipes, { id: crypto.randomUUID(), name, yield: yieldN, ingredients }] }))) onClose() }}><div className="form-grid two"><Field label="Recipe name"><input required value={name} onChange={e => setName(e.target.value)} /></Field><Field label="Number of servings"><input required type="number" min="1" max="100" value={yieldN} onChange={e => setYield(+e.target.value)} /></Field></div><Field label="Choose ingredient"><select value={foodId} onChange={e => setFoodId(e.target.value)}>{foods.map(f => <option key={f.id} value={f.id}>{f.name} · {f.unit}</option>)}</select></Field><div className="form-grid two"><Field label={`Quantity (${f.unit})`}><input type="number" min="0.1" max="100" step="0.1" value={q} onChange={e => setQ(+e.target.value)} /></Field><button type="button" className="button secondary align-bottom" disabled={q <= 0 || q > 100} onClick={() => setIngredients([...ingredients, { food: f, quantity: q, unit: f.unit }])}><Plus size={16} />Add ingredient</button></div>{ingredients.map((i, index) => <div className="record" key={index}><div>{i.quantity} {i.unit} {i.food.name}</div><IconButton label="Remove ingredient" onClick={() => setIngredients(ingredients.filter((_, n) => n !== index))}><X size={15} /></IconButton></div>)}<div className="notice">{fmt(total(ingredients.map(i => portion(i.food, i.quantity, i.unit).nutrition)).calories / (yieldN || 1))} estimated kcal per serving</div><button className="button full" disabled={!ingredients.length}>Save recipe</button></form></Modal> }
function Goals() { const { data, open, update } = useApp(); return <><PageHeading title="Goals that fit your routine" subtitle="Set a target, track your records and adjust as life changes." action={<button className="button" onClick={() => open('goal')}><Plus size={17} />New goal</button>} /><GoalPanel data={data} date={dayKey()} save={update}/>{data.goals.filter(g => g.status !== 'archived').length ? <div className="recipe-grid">{data.goals.filter(g => g.status !== 'archived').map(g => { const count = data.workouts.filter(w => w.date >= g.start && w.date <= g.end).length; return <Card title={g.title} subtitle={`${g.start} to ${g.end}`} key={g.id} action={<Target size={21} />}><div className="weight-value">{count}<span>/ {g.workouts} workouts</span></div><Progress value={count} max={g.workouts} /><p>{count >= g.workouts ? 'Goal achieved — a moment worth recognizing.' : `${Math.max(0, Math.ceil((new Date(g.end + 'T23:59:59').getTime() - Date.now()) / 86400000))} days remaining. Progress is based on recorded workouts.`}</p><button className="text-button" onClick={() => update(s => ({ ...s, goals: s.goals.map(x => x.id === g.id ? { ...x, status: 'archived' } : x) }))}>Archive goal</button></Card> })}</div> : <Card><Empty icon={Target} title="Start with something achievable" text="Set a weekly or monthly workout goal and watch your real records build progress." action="Create a goal" onClick={() => open('goal')} /></Card>}</> }
function GoalModal({ onClose }: any) { const { update } = useApp(); const [title, setTitle] = useState('Move three times this week'), [count, setCount] = useState(3), [start, setStart] = useState(dayKey()), [end, setEnd] = useState(shiftDay(dayKey(), 6)); return <Modal title="A goal that fits your life" description="Progress updates automatically from recorded workouts." onClose={onClose}><form onSubmit={async e => { e.preventDefault(); if (end < start) return; if (await update(s => ({ ...s, goals: [...s.goals, { id: crypto.randomUUID(), title, start, end, workouts: count, status: 'active' }] }))) onClose() }}><Field label="Goal name"><input required value={title} onChange={e => setTitle(e.target.value)} /></Field><Field label="Workout target"><input type="number" required min="1" max="100" value={count} onChange={e => setCount(+e.target.value)} /></Field><div className="form-grid two"><Field label="Start"><input type="date" required value={start} onChange={e => setStart(e.target.value)} /></Field><Field label="End"><input type="date" required min={start} value={end} onChange={e => setEnd(e.target.value)} /></Field></div><button className="button full">Create goal</button></form></Modal> }
function Supplements() { const { data, update, date, open } = useApp(); const taken = data.supplements.filter(s => s.taken.includes(date)).length; return <><PageHeading title="Your supplements" subtitle="Log your usual supplements and review their daily nutrition. Follow your product label for dosage." action={<button className="button" onClick={() => open('supplement')}><Plus size={17} />Add supplement</button>} /><div className="day-row"><h3>{data.supplementHistory.filter(r => r.date === date).length + taken} logged · {fmt(dailyBalance(data, date).supplements.calories)} kcal</h3><DateControl /></div><Card>{data.supplements.filter(s=>!s.archived).length ? data.supplements.filter(s=>!s.archived).map(s => <div className="record" key={s.id}><button aria-label={'Toggle taken: ' + s.name} className={s.taken.includes(date) ? 'exercise-check complete' : 'exercise-check'} onClick={() => update(d => ({ ...d, supplements: d.supplements.map(x => x.id === s.id ? { ...x, taken: x.taken.includes(date) ? x.taken.filter(d => d !== date) : [...x.taken, date] } : x) }))}>{s.taken.includes(date) ? <Check size={18} /> : <Pill size={18} />}</button><div><strong>{s.name} <span className="badge">Mine</span></strong><p>{s.amount} · User-entered label · {s.calories} kcal</p></div><IconButton label={'Archive ' + s.name} onClick={() => update(d => ({ ...d, supplements: d.supplements.map(x => x.id === s.id ? {...x,archived:true} : x) }))}><Trash2 size={16} /></IconButton></div>) : <Empty icon={Pill} title="Keep your routine in one place" text="Enter a product from its actual package label to start tracking it." action="Add a supplement" onClick={() => open('supplement')} />}</Card><SupplementProducts data={data} date={date} save={update}/><SupplementHistory data={data} date={date} save={update}/><p className="help">Logged supplements contribute calories, protein, carbs, fat and fiber to your daily totals. Saved daily-plan products retain their calories and protein. Avoid logging the same serving twice.</p></> }
function SupplementModal({ onClose }: any) { const { update, date } = useApp(); const [query, setQuery] = useState(''), [name, setName] = useState(''), [amount, setAmount] = useState(''), [quantity, setQuantity] = useState(1), [nutrition, setNutrition] = useState({ ...zero }), [confirmed, setConfirmed] = useState(false), [details,setDetails]=useState<Details>({}); return <Modal title="Log a supplement" description={`${dateLabel(date)} · separate from your meals, included in daily nutrition.`} onClose={onClose}><Field label="Search supplement catalog"><input placeholder="Surbex, whey, creatine, vitamin…" value={query} onChange={e => setQuery(e.target.value)} /></Field><div className="supplement-results">{supplementCatalog.filter(s => s.name.toLowerCase().includes(query.toLowerCase())).map(s => <button type="button" className="food-result" key={s.id} onClick={() => { setName(s.name); setAmount(s.amount); setNutrition({ calories: s.calories, protein: s.protein, carbs: s.carbs, fat: s.fat, fiber: s.fiber }); setConfirmed(false);setDetails({}) }}><span><strong>{s.name}</strong><small>{s.amount} · ≈ {s.calories} kcal · unverified catalog value</small></span><Plus size={15} /></button>)}</div><p className="help">Choose a catalog item or enter any product below. Confirm against your package: brands and variants differ. This is a log, not a dosage recommendation.</p><form onSubmit={async e => { e.preventDefault(); if (!confirmed || !name.trim() || !amount.trim() || !Number.isFinite(quantity) || quantity <= 0 || Object.values(nutrition).some(v => !Number.isFinite(v) || v < 0)) return; if (await update(s => ({ ...s, supplementHistory: [...s.supplementHistory, { id: crypto.randomUUID(), date, name: name.trim(), quantity, unit: amount, takenAt: new Date().toISOString(), nutrition: {...zero,...Object.fromEntries(Object.entries(nutrition).map(([k, v]) => [k, v * quantity])),details:scaleDetails(details,quantity)} as typeof zero }] }))) onClose() }}><Field label="Product and variant"><input required value={name} onChange={e => setName(e.target.value)} /></Field><div className="form-grid two"><Field label="One serving (from label)"><input required placeholder="1 scoop (30 g)" value={amount} onChange={e => setAmount(e.target.value)} /></Field><Field label="Servings taken"><input required type="number" min="0.1" max="100" step="0.1" value={quantity} onChange={e => setQuantity(+e.target.value)} /></Field></div><div className="form-grid two">{Object.entries(nutrition).map(([key, value]) => <Field key={key} label={key === 'calories' ? 'Calories per serving (kcal)' : key + ' per serving (g)'}><input required type="number" min="0" max="5000" step="0.1" value={value} onChange={e => setNutrition(n => ({ ...n, [key]: +e.target.value }))} /></Field>)}</div><NutrientFields value={details} onChange={setDetails}/><p className="help">This log adds ≈ {fmt(nutrition.calories * quantity)} kcal to your daily intake.</p><label className="checkbox-label"><input type="checkbox" required checked={confirmed} onChange={e => setConfirmed(e.target.checked)} />I checked the serving and nutrition against my product label.</label><button type="button" className="button secondary full" disabled={!confirmed||!name.trim()||!amount.trim()} onClick={async()=>{try{scaleDetails(details,1);if(Object.values(nutrition).some(v=>!Number.isFinite(v)||v<0))return;if(await update(s=>({...s,supplementProducts:[...(s.supplementProducts||[]),{id:crypto.randomUUID(),name:name.trim(),unit:amount,nutrition:{...nutrition,details}}]})))onClose()}catch{setConfirmed(false)}}}>Save product for reuse (no intake)</button><button className="button full">Log supplement</button></form></Modal> }
function Chef({ onClose }: any) { return <Modal title="Find your next meal" description="Meal ideas from ingredients you have." onClose={onClose}><Suspense fallback={<p role="status">Loading chef…</p>}><ChefAssistant /></Suspense></Modal> }
function AuthModal({ onClose }: any) { return <Modal title="Your CalNutriFit account" description="Sign in to save your journal and continue across devices." onClose={onClose}><AuthPanel onClose={onClose} /></Modal> }
function PasswordReset() { const [password, setPassword] = useState(''), [confirm, setConfirm] = useState(''), [message, setMessage] = useState(''), [busy, setBusy] = useState(false); return <Card title="Choose a new password"><form onSubmit={async e => { e.preventDefault(); if (password !== confirm) { setMessage('The passwords do not match.'); return } setBusy(true); try { if (!cloud) throw Error('Account service is not configured.'); const { data: { session } } = await cloud.auth.getSession(); if (!session) throw Error('Open the secure link in your reset email before choosing a password.'); const { error } = await cloud.auth.updateUser({ password }); if (error) throw error; setMessage('Password updated. You can now continue to your journal.'); setPassword(''); setConfirm('') } catch (e) { setMessage((e as Error).message) } finally { setBusy(false) } }}><Field label="New password"><input type="password" autoComplete="new-password" required minLength={8} value={password} onChange={e => setPassword(e.target.value)} /></Field><Field label="Confirm new password"><input type="password" autoComplete="new-password" required minLength={8} value={confirm} onChange={e => setConfirm(e.target.value)} /></Field><button className="button" disabled={busy}>{busy ? 'Updating…' : 'Update password'}</button><p role="status" className="help">{message}</p></form></Card> }
class ErrorBoundary extends React.Component<{ children: React.ReactNode }, { error: boolean }> { state = { error: false }; static getDerivedStateFromError() { return { error: true } } render() { return this.state.error ? <div className="loading"><h1>Something didn’t load correctly.</h1><p>Your saved journal has not been cleared.</p><button className="button" onClick={() => location.reload()}>Try again</button></div> : this.props.children } }
export default function JournalApp({initialMode}: {initialMode?: 'session'|'auth'|'demo'}) { return <ErrorBoundary><BrowserRouter><App initialMode={initialMode}/></BrowserRouter></ErrorBoundary> }
